const item = $input.first();
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) {
  throw new Error('No CSV file uploaded. Expected field leads.csv');
}
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const text = buffer.toString('utf8');
const lines = text.split(/\r?\n/).filter(l => l.trim());
if (lines.length < 2) {
  return [];
}
const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const rows = [];
for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(',').map(c => c.trim().replace(/^"|"$/g, ''));
  const obj = {};
  headers.forEach((h, idx) => { obj[h] = cols[idx] ?? ''; });
  const email = (obj.email || '').trim().toLowerCase();
  if (!emailRe.test(email)) continue;
  const campaign = (obj.campaign || '').trim();
  if (!campaign) continue;
  rows.push({
    campaign,
    email,
    first_name: (obj.first_name || '').trim() || null,
    company: (obj.company || '').trim() || null,
    title: (obj.title || '').trim() || null,
    domain: (obj.domain || '').trim() || null,
    source: (obj.source || 'csv').trim() || 'csv',
    icp_score: obj.icp_score !== '' && obj.icp_score != null ? parseInt(obj.icp_score, 10) : null,
    notes: (obj.notes || '').trim() || null,
  });
}
return rows.map(r => ({ json: r }));

const leads = $('Parse and Normalize CSV').all().map(i => i.json);
const suppressed = new Set(
  $('Get Suppression Emails').all().map(i => (i.json.email || '').toLowerCase())
);
const kept = leads.filter(l => !suppressed.has(l.email));
return kept.map(r => ({ json: r }));

