SET search_path TO hermes_outreach;
INSERT INTO leads (campaign, email, first_name, company, title, domain, source, icp_score, notes)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (campaign, lower(email)) DO NOTHING
RETURNING id;

