const parsed = $('Parse and Normalize CSV').all().length;
const afterSuppression = $('Filter Suppressed').all().length;
const inserted = $input.all().filter(i => i.json.id).length;
const skipped = afterSuppression - inserted;
return [{
  json: {
    parsed_rows: parsed,
    after_suppression_filter: afterSuppression,
    inserted,
    skipped,
    message: `Lead import complete: ${inserted} inserted, ${skipped} skipped (duplicate or conflict).`
  }
}];
